ion":"keep","level":"E2","claim":"B is part of the Class of '93 reunion","evidence":[{"turn_id":5,"quote":"your reunion memory book"}],"reason":"'Your reunion memory book' presupposes B is a participant/member of the reunion, as the book is designated for B at that event."},{"id":"c9","action":"keep","level":"E2","claim":"B is doing work at the reunion event","evidence":[{"turn_id":3,"quote":"Keep up the good work"},{"turn_id":3,"quote":"welcome to the reunion of the Class of ' 93"}],"reason":"'Keep up the good work' presupposes B is performing work, and the reunion context from the same turn establishes the location."}]}
